// Validate and parse scaffold request
const body = $input.item.json.body || $input.item.json;

const storyId = body.story_id;
const repoName = body.repo_name;
const template = body.template || 'default';
const rulesetId = body.ruleset_id;
const runId = body.run_id;
const org = body.org || 'aisha';
const branch = body.branch || 'main';
const deployProvider = body.deploy_provider || 'coolify';
const previewUrl = body.preview_url;

if (!storyId) {
  throw new Error('Missing required parameter: story_id');
}
if (!repoName) {
  throw new Error('Missing required parameter: repo_name');
}

return {
  json: {
    story_id: storyId,
    repo_name: repoName,
    template,
    ruleset_id: rulesetId,
    run_id: runId,
    org,
    branch,
    deploy_provider: deployProvider,
    preview_url: previewUrl,
    started_at: new Date().toISOString()
  }
};

// Step 1: Transition story to 'scaffolding' via MCP
const input = $input.item.json;

const mcpUrl = ($env?.AISHA_POSTGREST_URL || '') + '/functions/v1/mcp-knowledge-server';
const token = $env?.AISHA_ACCESS_TOKEN || $env?.AISHA_KEYCLOAK_ACCESS_TOKEN || '';

const rpcBody = JSON.stringify({
    jsonrpc: '2.0',
    id: Date.now(),
    method: 'tools/call',
    params: {
      name: 'transition_delivery_status',
      arguments: {
        story_id: input.story_id,
        new_status: 'scaffolding',
        trigger_source: 'workflow',
        metadata: { workflow: 'WF_STORY_SCAFFOLD', run_id: input.run_id }
      }
    }
  });

let data;
try {
  if (typeof fetch === 'function') {
    const res = await fetch(mcpUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token },
      body: rpcBody
    });
    data = await res.json();
  } else {
    const https = require('https');
    const url = new URL(mcpUrl);
    data = await new Promise((resolve, reject) => {
      const req = https.request({
        hostname: url.hostname,
        port: url.port || 443,
        path: url.pathname,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': 'Bearer ' + token,
          'Content-Length': Buffer.byteLength(rpcBody)
        }
      }, res => {
        let body = '';
        res.on('data', c => body += c);
        res.on('end', () => {
          try { resolve(JSON.parse(body)); }
          catch { reject(new Error('Invalid JSON response: ' + body.substring(0, 200))); }
        });
      });
      req.on('error', reject);
      req.write(rpcBody);
      req.end();
    });
  }
} catch (e) {
  return 'MCP Tool Error: ' + (e.message || String(e));
}
const success = !data.error;

return {
  json: {
    ...input,
    transition_to_scaffolding: success ? 'ok' : 'failed',
    transition_detail: data.error ? data.error.message : 'transitioned'
  }
};

// Step 2: Get story context (rules, participants, repo info)
