const mcpUrl = ($env?.AISHA_POSTGREST_URL || '') + '/functions/v1/mcp-knowledge-server';
const token = $env?.AISHA_ACCESS_TOKEN || $env?.AISHA_KEYCLOAK_ACCESS_TOKEN || '';

const rpcBody = JSON.stringify({
    jsonrpc: '2.0',
    id: Date.now(),
    method: 'tools/call',
    params: {
      name: 'get_story_context',
      arguments: {
        story_id: input.story_id
      }
    }
  });

let data;
try {
  if (typeof fetch === 'function') {
    const res = await fetch(mcpUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token },
      body: rpcBody
    });
    data = await res.json();
  } else {
    const https = require('https');
    const url = new URL(mcpUrl);
    data = await new Promise((resolve, reject) => {
      const req = https.request({
        hostname: url.hostname,
        port: url.port || 443,
        path: url.pathname,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': 'Bearer ' + token,
          'Content-Length': Buffer.byteLength(rpcBody)
        }
      }, res => {
        let body = '';
        res.on('data', c => body += c);
        res.on('end', () => {
          try { resolve(JSON.parse(body)); }
          catch { reject(new Error('Invalid JSON response: ' + body.substring(0, 200))); }
        });
      });
      req.on('error', reject);
      req.write(rpcBody);
      req.end();
    });
  }
} catch (e) {
  return 'MCP Tool Error: ' + (e.message || String(e));
}
let storyContext = {};
if (data.result?.content) {
  // Parse text/json content from MCP response
  for (const c of data.result.content) {
    if (c.type === 'resource' && c.resource?.text) {
      try { storyContext = JSON.parse(c.resource.text); } catch {}
    }
  }
}

return {
  json: {
    ...input,
    story_context: storyContext,
    rules_preview: storyContext.expert_rules_preview || [],
    repo_url: storyContext.repo_url || '',
    build_cmd: storyContext.build_config?.build_cmd || 'npm run build',
    node_version: storyContext.build_config?.node_version || '20'
  }
};

