  }
};

// Step 4: Generate copilot-instructions.md from story rules and context
const input = $input.item.json;

const rules = input.rules_preview || [];
const ctx = input.story_context || {};

const sections = [
  '# Copilot Instructions — Story Delivery',
  '',
  `> Auto-generated for story \`${input.story_id}\``,
  `> Repository: ${input.org}/${input.repo_name}`,
  `> Branch: ${input.story_branch}`,
  `> Generated: ${new Date().toISOString()}`,
  '',
  '---',
  '',
  '## Project Context',
  '',
  ctx.title ? `**Story:** ${ctx.title}` : '',
  ctx.program_name ? `**Program:** ${ctx.program_name}` : '',
  ctx.partner_name ? `**Partner:** ${ctx.partner_name}` : '',
  '',
  '## Build Configuration',
  '',
  `- **Node.js:** ${input.node_version}`,
  `- **Build command:** \`${input.build_cmd}\``,
  '',
];

// Add expert rules
if (rules.length > 0) {
  sections.push('## Expert Rules', '');
  for (const rule of rules) {
    sections.push(`### ${rule.title || rule.slug || 'Rule'}`);
    if (rule.description) sections.push('', rule.description);
    if (rule.content) sections.push('', rule.content);
    sections.push('');
  }
}

// Platform standards
sections.push(
  '## Platform Standards',
  '',
  '1. **RPC-Only** — No direct `.from()` queries, everything via `supabase.rpc()`',
  '2. **No sensitive data in logs** — Use `safeError()` for error logging',
  '3. **Explicit columns** — No `.select("*")`, always list needed columns',
  '4. **No hardcoded text** — All UI text via i18n `t()`',
  '5. **No `any` types** — Use proper types or `unknown` + type guard',
  '6. **No `console.log()`** — Error logging only via `safeError()`',
  '7. **Gate tests must pass** — `npm run test:gates`',
  '',
  '---',
  '',
  '> Managed by AISHA Dirigent. Do not edit manually.',
);

const instructionsContent = sections.filter(Boolean).join('\n');

return {
  json: {
    ...input,
    instructions_content: instructionsContent,
    instructions_path: '.github/copilot-instructions.md'
  }
};

